SELECT k.i, f.root FROM unnest($1::bytea[], $2::bigint[]) WITH ORDINALITY AS k(digest, length, i) LEFT JOIN ({s}.file_digest f JOIN {s}.object_location o ON ('x' || encode(substring(o.object_id FROM 1 FOR 8), 'hex'))::bit(64)::bigint = ('x' || encode(substring(f.root FROM 1 FOR 8), 'hex'))::bit(64)::bigint AND o.object_id = f.root) ON f.digest = k.digest AND f.length = k.length ORDER BY k.i;
